Fixpoint art_segs_in (segs : list Segment) (lo hi : Z) : bool :=
  match segs with
  | [] => true
  | s :: r => (lo <=? Z.of_N (seg_base s)) && (Z.of_N (seg_base s) + Z.of_N (seg_size s) <=? hi) && art_segs_in r lo hi
  end.

